declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('mailing.manage');
$id=max(1,(int)($_GET['id']??$_POST['id']??0));$st=db()->prepare('SELECT * FROM mailing_campaigns WHERE id=?');$st->execute([$id]);$campaign=$st->fetch();if(!$campaign){http_response_code(404);exit('Campaña no encontrada.');}$pageTitle='Enviar campaña';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$st=db()->prepare("SELECT * FROM mailing_recipients WHERE campaign_id=? AND status IN ('pending','failed') ORDER BY id LIMIT 100");$st->execute([$id]);$batch=$st->fetchAll();if(!$batch)$errors[]='No quedan destinatarios pendientes.';else{db()->prepare("UPDATE mailing_campaigns SET status='sending' WHERE id=?")->execute([$id]);$sent=0;$failed=0;foreach($batch as$r){$name=trim((string)($r['recipient_name']?:''));$company='';if($r['client_id']){$s=db()->prepare('SELECT company_name FROM clients WHERE id=?');$s->execute([(int)$r['client_id']]);$company=(string)($s->fetchColumn()?:'');}$message=str_replace(['{{NOMBRE}}','{{EMPRESA}}'],[$name,$company],(string)$campaign['html_content']);$html='<!doctype html><html><body style="margin:0;background:#edf3f7;padding:24px;font-family:Arial,sans-serif;color:#173247"><div style="max-width:720px;margin:auto;background:#fff;border:1px solid #dce7ed;border-radius:14px;overflow:hidden"><div style="height:6px;background:#ff5300"></div><div style="padding:28px"><div style="font-weight:800;color:#0074c7;font-size:18px;margin-bottom:20px">SÓCRATES · AI Creative Studio</div><div style="font-size:15px;line-height:1.7">'.nl2br(e($message)).'</div><div style="border-top:1px solid #e4edf2;margin-top:28px;padding-top:16px;color:#6b7e8b;font-size:12px">www.socrates.la</div></div></div></body></html>';$result=send_system_email((string)$r['email'],(string)$campaign['subject'],$html);db()->prepare('UPDATE mailing_recipients SET status=?,error_message=?,sent_at=? WHERE id=?')->execute([$result['success']?'sent':'failed',$result['error'],$result['success']?date('Y-m-d H:i:s'):null,(int)$r['id']]);$result['success']?$sent++:$failed++;}
 $remainingStmt=db()->prepare("SELECT COUNT(*) FROM mailing_recipients WHERE campaign_id=? AND status IN ('pending','failed')");$remainingStmt->execute([$id]);$remaining=(int)$remainingStmt->fetchColumn();db()->prepare("UPDATE mailing_campaigns SET sent_count=(SELECT COUNT(*) FROM mailing_recipients WHERE campaign_id=? AND status='sent'),failed_count=(SELECT COUNT(*) FROM mailing_recipients WHERE campaign_id=? AND status='failed'),status=?,sent_at=? WHERE id=?")->execute([$id,$id,$remaining===0?'sent':'sending',$remaining===0?date('Y-m-d H:i:s'):null,$id]);flash($failed?'warning':'success',"Lote procesado: {$sent} enviados y {$failed} fallidos.".($remaining?' Quedan '.$remaining.' pendientes.':''));redirect('mailing_view.php?id='.$id);}}
$st=db()->prepare("SELECT COUNT(*) FROM mailing_recipients WHERE campaign_id=? AND status IN ('pending','failed')");$st->execute([$id]);$pending=(int)$st->fetchColumn();require __DIR__.'/includes/header.php';
