<?php foreach($errors as$e):?><div class="alert alert-error"><?=e($e)?></div><?php endforeach;?><section class="panel"><div class="panel-header"><h2>Confirmar envío</h2></div><div class="panel-body"><div class="callout"><strong><?=e($campaign['name'])?></strong><p>Se enviará un máximo de 100 mensajes en este lote. Esto reduce bloqueos del servidor y permite revisar errores.</p><p><strong><?=$pending?></strong> destinatarios pendientes.</p></div><form method="post" class="form-actions"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><a class="btn btn-light" href="mailing_view.php?id=<?=$id?>">Cancelar</a><button class="btn btn-primary" <?=$pending<1?'disabled':''?>>ENVIAR AHORA</button></form></div></section><?php require __DIR__.'/includes/footer.php';?>
